 const [modal,setModal]=useState<Modal>(null),[search,setSearch]=useState(''),[department,setDepartment]=useState('All departments'),[campaignFilter,setCampaignFilter]=useState('All statuses');
 const [chosenTemplate,setChosenTemplate]=useState<Template>(templates[0]),[draft,setDraft]=useState<Campaign|null>(null),[editEmployee,setEditEmployee]=useState<Employee|null>(null);
 const [selectedCampaign,setSelectedCampaign]=useState<string|null>(null),[selectedDelivery,setSelectedDelivery]=useState<string|null>(null),[selectedModule,setSelectedModule]=useState<string|null>(null),[quiz,setQuiz]=useState<Record<number,string>>({}),[quizResult,setQuizResult]=useState<number|null>(null);
 const [confirmed,setConfirmed]=useState(false),[launchId,setLaunchId]=useState<string|null>(null),[resetMode,setResetMode]=useState<'sample'|'empty'|null>(null),[importText,setImportText]=useState(''),[includeInactive,setIncludeInactive]=useState(false);
 useEffect(()=>{setReady(true);},[]);
 const lastSaved=useRef(w);
 useEffect(()=>{if(ready&&lastSaved.current!==w){lastSaved.current=w;onWorkspaceChange(w);}},[w,ready,onWorkspaceChange]);
 const employee=w.employees.find(e=>e.id===employeeId&&e.active);
 const admin=role==='Administrator';const actor=admin?'Administrator':employee?.name??'Employee';
 const departments=['All departments',...Array.from(new Set(w.employees.map(e=>e.department)))];
 const available=w.employees.filter(e=>e.active);const stats=results(w,admin?undefined:employeeId);const trainingRate=completionRate(w,admin?undefined:employeeId);
 const notices=w.notices.filter(n=>n.employeeId===employeeId);const unread=notices.filter(n=>!n.read).length;
