 const selected=w.campaigns.find(c=>c.id===selectedCampaign),delivery=w.deliveries.find(d=>d.id===selectedDelivery&&d.employeeId===employeeId),deliveryCampaign=w.campaigns.find(c=>c.id===delivery?.campaignId),lesson=modules.find(m=>m.id===selectedModule);
 const departmentStats=departments.slice(1).map(d=>{const ids=w.employees.filter(e=>e.active&&e.department===d).map(e=>e.id);const ds=w.deliveries.filter(x=>ids.includes(x.employeeId));return {name:d,clickRate:percent(ds.filter(x=>x.clicked).length,ds.length),training:percent(w.completions.filter(c=>c.score>=80&&ids.includes(c.employeeId)).length,ids.length*modules.length),count:ids.length};});
